## Spring Cloud Gateway — Configuration

```yaml
# application.yml
spring:
  cloud:
    gateway:
      routes:
        # Order Service route
        - id: order-service
          uri: lb://ORDER-SERVICE     # lb:// = load balancer (via Eureka)
          predicates:
            - Path=/api/orders/**
          filters:
            - StripPrefix=1           # Remove /api prefix before forwarding
            - name: RequestRateLimiter
              args:
                redis-rate-limiter.replenishRate: 100   # tokens/sec
                redis-rate-limiter.burstCapacity: 200   # max burst
            - name: CircuitBreaker
              args:
                name: orderCircuitBreaker
                fallbackUri: forward:/fallback/orders

        # User Service route
        - id: user-service
          uri: lb://USER-SERVICE
          predicates:
            - Path=/api/users/**
          filters:
            - AddRequestHeader=X-Service-Name, gateway
            - AddResponseHeader=X-Request-Id, #{T(java.util.UUID).randomUUID()}

        # Auth Service — no JWT filter (it IS the auth service)
        - id: auth-service
          uri: lb://AUTH-SERVICE
          predicates:
            - Path=/api/auth/**
```

## JWT Authentication Filter

```java
@Component
public class JwtAuthenticationFilter implements GlobalFilter, Ordered {

    private final JwtTokenProvider jwtProvider;

    // Paths that don't need authentication:
    private static final List<String> PUBLIC_PATHS = List.of(
        "/api/auth/login",
        "/api/auth/register",
        "/api/auth/refresh"
    );

    @Override
    public Mono<Void> filter(ServerWebExchange exchange, GatewayFilterChain chain) {
        String path = exchange.getRequest().getPath().value();

        if (PUBLIC_PATHS.stream().anyMatch(path::startsWith)) {
            return chain.filter(exchange);  // Skip auth for public paths
        }

        String authHeader = exchange.getRequest().getHeaders().getFirst(HttpHeaders.AUTHORIZATION);
        if (authHeader == null || !authHeader.startsWith("Bearer ")) {
            return unauthorized(exchange);
        }

        String token = authHeader.substring(7);
        try {
            Claims claims = jwtProvider.validateAndExtract(token);

            // Add user info as headers to downstream services:
            ServerHttpRequest mutatedRequest = exchange.getRequest().mutate()
                .header("X-User-Id", claims.getSubject())
                .header("X-User-Role", claims.get("role", String.class))
                .build();

            return chain.filter(exchange.mutate().request(mutatedRequest).build());
        } catch (JwtException e) {
            return unauthorized(exchange);
        }
    }

    private Mono<Void> unauthorized(ServerWebExchange exchange) {
        exchange.getResponse().setStatusCode(HttpStatus.UNAUTHORIZED);
        return exchange.getResponse().setComplete();
    }

    @Override
    public int getOrder() { return -1; }  // Run before other filters
}
```

## Rate Limiting with Redis

```java
@Configuration
public class GatewayConfig {

    @Bean
    public KeyResolver userKeyResolver() {
        // Rate limit per user (from JWT header added by auth filter):
        return exchange -> Mono.justOrEmpty(
            exchange.getRequest().getHeaders().getFirst("X-User-Id")
        ).switchIfEmpty(Mono.just("anonymous"));
    }

    @Bean
    public RedisRateLimiter redisRateLimiter() {
        return new RedisRateLimiter(
            100,   // Tokens replenished per second
            200,   // Max burst capacity
            1      // Requested tokens per request
        );
    }
}
```

## BFF Pattern (Backend for Frontend)

```
CLIENT TYPES vs GATEWAY:

  Mobile App
      ↓
  Mobile BFF Gateway   → aggregates 3 service calls into 1 (bandwidth concern)
      ↓  ↓  ↓
  Orders  Users  Products

  Web App
      ↓
  Web BFF Gateway      → returns full response (bandwidth not a concern)
      ↓  ↓  ↓
  Orders  Users  Products

  External Partners
      ↓
  Public API Gateway   → strict rate limiting, API keys, SLA enforcement
      ↓  ↓  ↓
  Same services

Benefit: mobile BFF can reduce 3 round trips to 1 by aggregating.
Downside: more gateways to maintain.
```

## Production Reality

Don't put business logic in the gateway — the moment you do, it becomes hard to test and couples your clients to internal implementation. The gateway should only: route, authenticate JWTs (validate signature and extract claims), rate limit, log request/response metadata, and handle circuit breaking. Service-specific logic stays in services. Deploy the gateway with at least 3 instances and put it behind a load balancer.
